457	            .append("address", this.address)
458	            .append("city", this.city)
459	            .append("telephone", this.telephone)
460	            .append("email", this.email)
461	            .append("registrationDate", this.registrationDate)
462	            .append("customerCode", this.customerCode)
463	            .toString();
464	    }
